//
// The parameter model for the orb: what a preset is, what a developer can move,
// and how far. Kept as a near-exact port of the upstream presets.ts so that the
// uniform packer next door stays a one-to-one mirror of the shader's struct. If
// a field is renamed here it has to be renamed in the shader too.

/** The eleven shipped looks. The name is also the wire value stored in the DB. */
export type OrbStyle =
  | "siri"
  | "voiceWave"
  | "spectrum"
  | "aurora"
  | "frost"
  | "plasma"
  | "chrome"
  | "opal"
  | "blueDrop"
  | "violetEmber"
  | "chromaticMetal"
  | "voxide"
  | "porcelain";

/**
 * Every value the shader reads, minus size and time which the renderer owns.
 *
 * Field order is meaningless here but load-bearing in `writeOrbUniforms`, which
 * packs these into a fixed 128-float buffer laid out to match `struct Uniforms`
 * in effect.wgsl.
 */
export type OrbParams = {
  style: OrbStyle;
  glassEnabled: boolean;

  // Motion
  speed: number;
  radius: number;

  // Shape
  contourDeform: number;
  zoom: number;
  warp: number;
  ridgeAmt: number;
  sharp: number;

  // Chromatic Metal only
  bandDensity: number;
  chromaticShift: number;
  metalScale: number;
  metalStretch: number;
  metalAngle: number;
  metalOffset: number;
  metalPhase: number;
  metalEvolution: number;
  metalRoughness: number;
  metalDepth: number;

  // Light
  shade: number;
  sheen: number;
  gloss: number;
  exposure: number;

  // Glass shell
  glassOpacity: number;
  shellMidAlpha: number;
  shellEdgeAlpha: number;

  // Edge
  edgeSoftness: number;
  edgeGlow: number;

  // Colors, all `#RRGGBB`
  colorA: string;
  colorB: string;
  colorC: string;
  colorD: string;
  highlightColor: string;
  shellInner: string;
  shellMid: string;
  shellEdge: string;
  sheenColor: string;
  specColor: string;
  /**
   * The base tone the fluid composites over, at effect.wgsl:1076. Upstream
   * calls this `canvasColor`, which reads like a page background and is not one
   * - the widget canvas is transparent and this never touches the host page.
   * The wire name is kept for shader parity; the dashboard labels it Core Tone.
   */
  canvasColor: string;
  glowColor: string;
};

/** Numeric keys only, for slider generation and clamping. */
export type OrbNumericKey = {
  [K in keyof OrbParams]: OrbParams[K] extends number ? K : never;
}[keyof OrbParams];

/** Color keys only, for swatch generation and hex validation. */
export type OrbColorKey = {
  [K in keyof OrbParams]: K extends "style"
    ? never
    : OrbParams[K] extends string
      ? K
      : never;
}[keyof OrbParams];

export const ORB_COLOR_KEYS: readonly OrbColorKey[] = [
  "colorA",
  "colorB",
  "colorC",
  "colorD",
  "highlightColor",
  "shellInner",
  "shellMid",
  "shellEdge",
  "sheenColor",
  "specColor",
  "canvasColor",
  "glowColor",
];

/**
 * Which flow program the shader dispatches to, by style. These are not
 * sequential and must not be renumbered: the values are matched against
 * literals in `glsPresetFluid` and `orbGlassLiquidAnim`.
 */
