  // A style is a named look, not a shader program. Several styles can share a
  // flow: "voxide" is the Siri flow in our own colours and "porcelain" is the
  // Frost flow with a light body, and neither needed a line of WGSL.
  voxide: 9,
  porcelain: 15,
  siri: 9,
  voiceWave: 19,
  aurora: 10,
  plasma: 11,
  chrome: 12,
  opal: 13,
  spectrum: 14,
