// ── Ranges ──────────────────────────────────────────────────────────────────

export type OrbNumericSpec = {
  key: OrbNumericKey;
  label: string;
  min: number;
  max: number;
  step: number;
  /**
   * Styles this control does anything for. Absent means every style. The
   * dashboard hides rather than disables the ones that do not apply - a
   * disabled slider that never becomes enabled is just noise.
   */
  styles?: readonly OrbStyle[];
};

