const SPEC_BY_KEY = new Map<OrbNumericKey, OrbNumericSpec>(
  ORB_NUMERIC_SPECS.map((spec) => [spec.key, spec]),
);

export function orbNumericSpec(key: OrbNumericKey): OrbNumericSpec | undefined {
  return SPEC_BY_KEY.get(key);
}

/** Whether a control is meaningful for a style. Absent `styles` means always. */
export function orbSpecApplies(spec: OrbNumericSpec, style: OrbStyle): boolean {
  return !spec.styles || spec.styles.includes(style);
}

