export const DEFAULT_ORB_STYLE: OrbStyle = "voxide";

export function orbPreset(style: OrbStyle): OrbParams {
  return { style, ...ORB_PRESETS[style] };
}

export const DEFAULT_ORB_PARAMS: OrbParams = orbPreset(DEFAULT_ORB_STYLE);

// ── Sanitising ──────────────────────────────────────────────────────────────

const HEX = /^#[0-9a-f]{6}$/i;

function clamp(value: number, min: number, max: number): number {
  return Math.min(max, Math.max(min, value));
}

/**
 * Build a complete, in-range OrbParams from whatever arrived over the wire.
 *
 * The dashboard writes these into an unvalidated JSONB column, so by the time
 * they reach the renderer they are `unknown`. A NaN or an Infinity here does
 * not throw, it silently produces a black or blown-out sphere on a customer's
 * production site, so every field is range-checked and anything unusable falls
 * back to its preset value.
 */
export function normalizeOrbParams(input: unknown): OrbParams {
  const raw = (input && typeof input === "object" ? input : {}) as Record<string, unknown>;

  const style: OrbStyle =
    typeof raw.style === "string" && raw.style in ORB_PRESETS
      ? (raw.style as OrbStyle)
      : DEFAULT_ORB_STYLE;

  const params = orbPreset(style);

  for (const spec of ORB_NUMERIC_SPECS) {
    const value = raw[spec.key];
    if (typeof value === "number" && Number.isFinite(value)) {
      params[spec.key] = clamp(value, spec.min, spec.max);
    }
  }

  for (const key of ORB_COLOR_KEYS) {
    const value = raw[key];
    if (typeof value === "string" && HEX.test(value)) {
      params[key] = value.toUpperCase();
    }
  }

  if (typeof raw.glassEnabled === "boolean") {
    params.glassEnabled = raw.glassEnabled;
  }

  return params;
}
