//
// The WebGPU renderer.
//
// Upstream's version runs in an editor on a machine the author controls. This
// one runs in a 56px circle on a stranger's website, on their battery, next to
// their own code, so it carries a set of obligations the original does not:
//
//   - it never renders when nobody can see it (tab hidden, launcher scrolled
//     off, element detached),
//   - it caps device pixel ratio rather than honouring a 3x phone,
//   - it can be told to run slower when the agent is asleep,
//   - it honours prefers-reduced-motion by freezing time rather than by
//     disappearing, so the orb is still there and still reflects agent state,
//   - and every failure path calls `onError` exactly once so the widget can
//     fall back to the DOM waveform instead of leaving a hole in the page.

import { ORB_EFFECT_WGSL } from "./shader";
import { writeOrbUniforms, ORB_UNIFORM_FLOATS } from "./uniforms";
import type { OrbParams } from "./params";

/**
 * A device pixel ratio above this buys nothing at the sizes an orb is drawn at
 * and costs 2.25x the fragments on a 3x phone, which is the difference between
 * free and noticeable on someone else's page.
 */
const MAX_DPR = 1.5;

/** The fullscreen triangle and the alpha composite. Appended to the effect. */
const ENTRY_POINTS = `
struct VOut {
  @builtin(position) pos: vec4<f32>,
  @location(0) uv: vec2<f32>,
};

@vertex
fn vs_main(@builtin(vertex_index) i: u32) -> VOut {
  var p = array<vec2<f32>, 3>(
    vec2<f32>(-1.0, -1.0),
    vec2<f32>( 3.0, -1.0),
    vec2<f32>(-1.0,  3.0),
  );
  var out: VOut;
  out.pos = vec4<f32>(p[i], 0.0, 1.0);
  let uv01 = (p[i] + vec2<f32>(1.0)) * 0.5;
  out.uv = vec2<f32>(uv01.x, 1.0 - uv01.y);
  return out;
}

@fragment
fn fs_main(in: VOut) -> @location(0) vec4<f32> {
  let c = orbGlassLiquidAnim(in.uv);

  let fc = vec2<f32>(in.uv.x, 1.0 - in.uv.y) * u.size;
  let uv = (2.0 * fc - u.size) / max(min(u.size.x, u.size.y), 1.0);
  let rad = max(u.radius, 0.05);
  let t = u.time * u.speed;
  let contourRad = rad * glsContourScale(uv, t, u.contourDeform);
  let pd = length(uv) / contourRad;
  let ballA = 1.0 - smoothstep(
    0.99 - mfEdgeD(u.edgeSoftness),
    1.01 + mfEdgeD(u.edgeSoftness),
    pd,
  );
  let lum = max(c.r, max(c.g, c.b));
  let q = (2.0 * fc - u.size) / u.size;
  let fitEnd = 1.0;
  let fitFeather = 2.0 / max(min(u.size.x, u.size.y), 1.0);
  let fitStart = min(mix(contourRad, fitEnd, 0.5), fitEnd - fitFeather);
  let fit = 1.0 - smoothstep(fitStart, fitEnd, max(abs(q.x), abs(q.y)));
  let alpha = select(ballA, max(ballA, lum), u.edgeGlow > 0.0);

  return vec4<f32>(c.rgb * fit, clamp(alpha, 0.0, 1.0) * fit);
}
`;

export function orbShaderSource(): string {
  return `${ORB_EFFECT_WGSL}\n${ENTRY_POINTS}`;
}

/** True when the browser exposes a WebGPU entry point at all. Synchronous. */
export function isOrbSupported(): boolean {
  return typeof navigator !== "undefined" && "gpu" in navigator && !!navigator.gpu;
}

export function prefersReducedMotion(): boolean {
  if (typeof window === "undefined" || !window.matchMedia) return false;
  try {
    return window.matchMedia("(prefers-reduced-motion: reduce)").matches;
  } catch {
    return false;
  }
}

/**
 * Ask for a real adapter.
 *
 * `navigator.gpu` existing is not the same as an adapter being available: a
 * blocklisted driver, a headless container or a browser out of GPU processes
 * all present the API and then hand back null. Callers that want to decide
 * between the orb and the waveform before painting anything should await this
 * rather than trusting `isOrbSupported`.
 */
export async function probeOrbSupport(): Promise<boolean> {
  if (!isOrbSupported()) return false;
  try {
    const adapter = await navigator.gpu.requestAdapter();
    return !!adapter;
  } catch {
    return false;
  }
}

export type OrbRendererOptions = {
  canvas: HTMLCanvasElement;
  /** Read once per frame. Return live values; the renderer holds no state. */
  getParams: () => OrbParams;
  /**
   * Frames per second to aim for, read once per frame. The widget lowers this
   * while the agent is idle. Anything at or above 60 means uncapped.
   */
  getTargetFps?: () => number;
  /** Called at most once. After this the renderer has stopped for good. */
  onError: (error: Error) => void;
  /** Called on the first successfully submitted frame. */
  onReady?: () => void;
};

/** Tears the renderer down. Safe to call more than once. */
export type OrbRendererHandle = () => void;

export function createOrbRenderer(options: OrbRendererOptions): OrbRendererHandle {
  const { canvas, getParams, getTargetFps, onError, onReady } = options;

  let disposed = false;
  let stopped = false;
  let frameHandle = 0;
  let device: GPUDevice | null = null;
  let readyNotified = false;

  let offscreen = false;

  let observer: IntersectionObserver | null = null;
  const reducedMotion = prefersReducedMotion();

  function teardown(): void {
    cancelAnimationFrame(frameHandle);
    frameHandle = 0;
    observer?.disconnect();
    observer = null;
    device?.destroy();
    device = null;
  }

  function fail(error: Error): void {
    if (stopped) return;
    stopped = true;
    teardown();
    if (!disposed) onError(error);
  }

  /**
   * Whether this frame would be wasted.
   *
   * Visibility is read here rather than cached from a `visibilitychange`
   * listener. A widget mounted in a background tab (cmd-click, target=_blank,
   * a prerender) would sample "hidden" at construction, and if the visitor
   * switched to the tab during the adapter and device and shader-compile
   * awaits, that transition landed before the listener existed and was lost.
   * The renderer then skipped every frame forever: no first frame, so no
   * `onReady`, and no error either, so the widget sat blank with nothing to
   * fall back to. Reading the live value cannot go stale.
   */
  function paused(): boolean {
    if (offscreen) return true;
    return typeof document !== "undefined" && document.visibilityState === "hidden";
  }

  async function start(): Promise<void> {
    if (!isOrbSupported()) {
      throw new Error("WebGPU is not available in this browser");
    }

    const adapter = await navigator.gpu.requestAdapter();
    if (!adapter) throw new Error("No WebGPU adapter is available");

    device = await adapter.requestDevice();
    if (disposed) {
      device.destroy();
      device = null;
      return;
    }

    const context = canvas.getContext("webgpu");
    if (!context) throw new Error("Could not create a WebGPU canvas context");

    const format = navigator.gpu.getPreferredCanvasFormat();
    // Premultiplied so the orb composites over whatever the host page has
    // behind it. The canvas itself never paints a background.
    context.configure({ device, format, alphaMode: "premultiplied" });

    const shader = device.createShaderModule({
      label: "voxide-orb",
      code: orbShaderSource(),
    });

    // Compilation errors are reported, not thrown, and a pipeline built on a
    // broken module renders nothing rather than failing. Check before building.
    const info = await shader.getCompilationInfo();
    const errors = info.messages.filter((m) => m.type === "error");
    if (errors.length > 0) {
      throw new Error(
        `Orb shader failed to compile: ${errors
          .map((m) => `${m.lineNum}:${m.linePos} ${m.message}`)
          .join("; ")}`,
      );
    }

    if (disposed) {
      // Optional chaining is load-bearing: teardown() may already have run
      // and nulled this during the compile await above. TypeScript cannot see
      // that, because the narrowing from requestDevice() survives the await.
      device?.destroy();
      device = null;
      return;
    }

    const pipeline = device.createRenderPipeline({
      label: "voxide-orb-pipeline",
      layout: "auto",
      vertex: { module: shader, entryPoint: "vs_main" },
      fragment: { module: shader, entryPoint: "fs_main", targets: [{ format }] },
      primitive: { topology: "triangle-list" },
    });

    const values = new Float32Array(ORB_UNIFORM_FLOATS);
    const uniformBuffer = device.createBuffer({
      label: "voxide-orb-uniforms",
      size: values.byteLength,
      usage: GPUBufferUsage.UNIFORM | GPUBufferUsage.COPY_DST,
    });
    const bindGroup = device.createBindGroup({
      layout: pipeline.getBindGroupLayout(0),
      entries: [{ binding: 0, resource: { buffer: uniformBuffer } }],
    });

    // A lost device is not recoverable in place. Report it and let the widget
    // decide, which it does by falling back to the DOM waveform. `destroy()`
    // also resolves this promise, so an intentional teardown is ignored.
    device.lost.then((info) => {
      if (disposed || stopped) return;
      fail(new Error(`WebGPU device lost: ${info.message || info.reason}`));
    });
    device.addEventListener("uncapturederror", (event) => {
      event.preventDefault();
      const err = (event as GPUUncapturedErrorEvent).error;
      fail(new Error(`WebGPU error: ${err.message}`));
    });

    // A launcher scrolled out of view, or inside a closed panel, should cost
    // nothing. Guarded because IntersectionObserver is absent in some embedded
    // webviews, where the fallback is simply to keep rendering.
    if (typeof IntersectionObserver !== "undefined") {
      observer = new IntersectionObserver(
        (entries) => {
          for (const entry of entries) offscreen = !entry.isIntersecting;
        },
        { threshold: 0 },
      );
      observer.observe(canvas);
    }

    const startedAt = performance.now();
    let lastDraw = 0;

    function resize(): boolean {
      const dpr = Math.min(window.devicePixelRatio || 1, MAX_DPR);
      const width = Math.max(1, Math.floor(canvas.clientWidth * dpr));
      const height = Math.max(1, Math.floor(canvas.clientHeight * dpr));

      if (canvas.width !== width || canvas.height !== height) {
        canvas.width = width;
        canvas.height = height;
      }
      // A detached or display:none canvas measures zero. Drawing into it is
      // legal and pointless, so treat it as another reason to skip the frame.
      return canvas.clientWidth > 0 && canvas.clientHeight > 0;
    }

    function frame(now: number): void {
      if (disposed || stopped || !device) return;
      frameHandle = requestAnimationFrame(frame);

      if (paused()) return;

      const target = getTargetFps ? getTargetFps() : 60;
      if (target < 60) {
        const minInterval = 1000 / Math.max(1, target);
        if (now - lastDraw < minInterval) return;
      }
      lastDraw = now;

      try {
        if (!resize()) return;

        // Reduced motion freezes the clock rather than the renderer. The orb
        // stays on the page and still answers state changes; it just does not
        // move on its own.
        const time = reducedMotion ? 0 : (now - startedAt) / 1000;

        writeOrbUniforms(values, canvas.width, canvas.height, time, getParams());
        device.queue.writeBuffer(uniformBuffer, 0, values);

        const encoder = device.createCommandEncoder();
        const pass = encoder.beginRenderPass({
          colorAttachments: [
            {
              view: context!.getCurrentTexture().createView(),
              clearValue: { r: 0, g: 0, b: 0, a: 0 },
              loadOp: "clear",
              storeOp: "store",
            },
          ],
        });
        pass.setPipeline(pipeline);
        pass.setBindGroup(0, bindGroup);
        pass.draw(3, 1, 0, 0);
        pass.end();
        device.queue.submit([encoder.finish()]);

        if (!readyNotified) {
          readyNotified = true;
          onReady?.();
        }
      } catch (error) {
        fail(error instanceof Error ? error : new Error(String(error)));
      }
    }

    frameHandle = requestAnimationFrame(frame);
  }

  start().catch((error: unknown) => {
    fail(error instanceof Error ? error : new Error(String(error)));
  });

  return () => {
    if (disposed) return;
    disposed = true;
    stopped = true;
    teardown();
  };
}
